WITH session_stats AS (SELECT session_id, SUM(CASE WHEN page = '/product' THEN duration_sec ELSE 0 END) AS product_duration_sec, MIN(duration_sec) AS min_duration_sec FROM web_events WHERE event_type IN ('add_to_cart', 'click') GROUP BY session_id) SELECT s.browser, s.customer_id, ss.product_duration_sec, ss.min_duration_sec FROM sessions s JOIN session_stats ss ON s.id = ss.session_id ORDER BY 4;
